def make_processor(start):
    value = start
    def apply(command):
        nonlocal value
        parts = command.split()
        op = parts[0]
        if op == 'ADD':
            value += int(parts[1])
        elif op == 'SUB':
            value -= int(parts[1])
        elif op == 'MUL':
            value *= int(parts[1])
        else:
            value = start
        return value
    return apply

start = int(input())
n = int(input())
apply = make_processor(start)
for _ in range(n):
    print(apply(input().strip()))

